content.content:
===== POST /v1/oauth/token
{
 "summary": "OAuth2 client credentials token",
 "description": null,
 "parameters": null,
 "requestBody": {
  "required": true,
  "content": {
   "application/x-www-form-urlencoded": {
    "schema": {
     "type": "object",
     "required": [
      "grant_type",
      "client_id",
      "client_secret"
     ],
     "properties": {
      "grant_type": {
       "type": "string",
       "enum": [
        "client_credentials"
       ]
      },
      "client_id": {
       "type": "string"
      },
      "client_secret": {
       "type": "string"
      }
     }
    }
   }
  }
 },
 "responses": {
  "200": {
   "description": "Access token",
   "content": {
    "application/json": {
     "schema": {
      "type": "object",
      "required": [
       "access_token",
       "token_type",
       "expires_in"
      ],
      "properties": {
       "access_token": {
        "type": "string"
       },
       "token_type": {
        "type": "string",
        "enum": [
         "Bearer"
        ]
       },
       "expires_in": {
        "type": "integer"
       },
       "scope": {
        "type": "string"
       }
      }
     }
    }
   }
  },
  "401": {
   "$ref": "#/components/responses/Problem"
  }
 },
 "security": null
}
===== GET /v1/quota
{
 "summary": "Quota status (authenticated client)",
 "description": "Returns the authenticated client's per-minute quota: rolling 60s window usage when the BFF uses Firestore (`backend: firestore`), or a process-local notice when quota is enforced only in-memory on each instance (`backend: process_local`). This call is authenticated like other `/v1` routes and counts toward the same rate limit when enforcement is enabled.",
 "parameters": null,
 "requestBody": null,
 "responses": {
  "200": {
   "description": "Quota snapshot",
   "content": {
    "application/json": {
     "schema": {
      "type": "object",
      "properties": {
       "data": {
        "type": "object",
        "required": [
         "clientId",
         "backend"
        ],
        "properties": {
         "clientId": {
          "type": "string"
         },
         "backend": {
          "type": "string",
          "enum": [
           "firestore",
           "process_local"
          ]
         },
         "limitPerMinute": {
          "type": "integer",
          "description": "Maximum requests per rolling minute for this client"
         },
         "usedInWindow": {
          "type": "integer",
          "description": "Requests recorded in the current 60s window (Firestore backend)"
         },
         "remainingInWindow": {
          "type": "integer",
          "description": "Remaining requests in the current window (Firestore backend)"
         },
         "windowStartedAt": {
          "type": "string",
          "format": "date-time",
          "description": "Start of the rolling window (ISO 8601, Firestore backend)"
         },
         "windowEndsAt": {
          "type": "string",
          "format": "date-time",
          "description": "End of the rolling window (ISO 8601, Firestore backend)"
         },
         "message": {
          "type": "string",
          "description": "Present when `backend` is `process_local`"
         }
        }
       }
      }
     }
    }
   }
  },
  "401": {
   "$ref": "#/components/responses/Problem"
  },
  "429": {
   "$ref": "#/components/responses/Problem"
  }
 },
 "security": [
  {
   "bearerAuth": []
  }
 ]
}
===== GET /v1/products/{id}
{
 "summary": "Get product by id",
 "description": null,
 "parameters": [
  {
   "name": "id",
   "in": "path",
   "required": true,
   "schema": {
    "type": "string"
   }
  },
  {
   "name": "brand",
   "in": "query",
   "description": "Same as list: distribution channel brand / domain. If omitted, CONTENT_DEFAULT_CHANNEL_DOMAIN must be set.",
   "schema": {
    "type": "string"
   }
  },
  {
   "name": "locale",
   "in": "query",
   "description": "Locale (e.g. it).",
   "schema": {
    "type": "string"
   }
  },
  {
   "name": "extended",
   "in": "query",
   "description": "Internal clients only. When true, returns the extended internal product payload including raw CMS attributes. External clients receive 403.",
   "schema": {
    "type": "boolean",
    "default": false
   }
  }
 ],
 "requestBody": null,
 "responses": {
  "200": {
   "description": "Product",
   "content": {
    "application/json": {
     "schema": {
      "type": "object",
      "properties": {
       "data": {
        "oneOf": [
         {
          "$ref": "#/components/schemas/ProductDetail"
         },
         {
          "$ref": "#/components/schemas/ProductExtended"
         }
        ]
       }
      }
     }
    }
   }
  },
  "400": {
   "$ref": "#/components/responses/Problem"
  },
  "401": {
   "$ref": "#/components/responses/Problem"
  },
  "403": {
   "$ref": "#/components/responses/Problem"
  },
  "404": {
   "$ref": "#/components/responses/Problem"
  },
  "502": {
   "$ref": "#/components/responses/Problem"
  }
 },
 "security": [
  {
   "bearerAuth": []
  }
 ]
}
===== POST /v1/itineraries
{
 "summary": "Create itinerary (internal)",
 "description": "Create a new itinerary (shopping cart) on the brand site for the resolved `?brand=`. Returns the `itineraryId` to use on every subsequent checkout call. Internal clients only \u2014 requires `profile=internal` and `allowedEntities` includes `itineraries`.",
 "parameters": [
  {
   "$ref": "#/components/parameters/BrandQuery"
  },
  {
   "$ref": "#/components/parameters/LocaleQuery"
  }
 ],
 "requestBody": {
  "required": true,
  "content": {
   "application/json": {
    "schema": {
     "type": "object",
     "required": [
      "productId",
      "startDate",
      "adults",
      "rooms"
     ],
     "properties": {
      "productId": {
       "oneOf": [
        {
         "type": "integer"
        },
        {
         "type": "string"
        }
       ],
       "description": "Product identifier for the brand site. Accept either the numeric CMS id returned by `GET /v1/products` (e.g. `181`) or the alphanumeric trip / provider code (e.g. `t0054825`, returned by `GET /v1/products/tripcode/...`)."
      },
      "startDate": {
       "type": "string",
       "format": "date",
       "description": "Trip start date (`YYYY-MM-DD`)."
      },
      "adults": {
       "type": "integer",
       "minimum": 1,
       "description": "Number of adult passengers."
      },
      "rooms": {
       "type": "integer",
       "minimum": 1,
