##### keys.js
/**
 * The key chain UI.
 *
 * This file is worth reading if you are a candidate, and worth nothing to you.
 * It submits a string and renders whatever the server says came back. The keys
 * are not here, the answers are not here, and the next stage's brief only
 * exists in a response the server declines to send until you have earned it.
 */
(() => {
  const api = window.VELA_API;
  const state = window.VELA_STATE;
  const { formatDuration, escapeHtml } = window.VELA_APP;

  const $ = id => document.getElementById(id);

  function setStatus(message, tone) {
    const el = $("keyStatus");
    if (!el) return;
    el.textContent = message || "";
    el.classList.toggle("is-error", tone === "error");
    el.classList.toggle("is-ok", tone === "ok");
  }

  function render(data) {
    if (!data?.started) return;
    const keys = data.keys;

    $("keyProgress").textContent = `${keys.found} of ${keys.total} found`;
    $("keyEarned").textContent = keys.bonusHours ? `+${keys.bonusHours}h earned` : "";

    $("keyList").innerHTML = keys.solved
      .map(
        stage =>
          `<li><span class="key-order">${stage.order}</span> ${escapeHtml(stage.label)} ` +
          `<span class="key-reward">+${Math.round(stage.rewardMs / 60000)}m</span></li>`
      )
      .join("");

    const next = $("keyNext");
    const form = $("keyForm");

    if (!keys.next) {
      next.innerHTML =
        '<div class="key-done"><strong>The chain is complete.</strong> ' +
        "Five keys, five hours. Put the time to use.</div>";
      form.classList.add("hidden");
      return;
    }

    form.classList.remove("hidden");
    next.innerHTML =
      `<div class="key-card">` +
      `<div class="key-card-head">` +
      `<span class="key-order">${keys.next.order}</span>` +
      `<h3>${escapeHtml(keys.next.brief.title)}</h3>` +
      `<span class="key-reward">+${Math.round(keys.next.rewardMs / 60000)}m</span>` +
      `</div>` +
      `<p>${escapeHtml(keys.next.brief.body)}</p>` +
      `</div>`;
  }

  function showReward(stage, data) {
    const dialog = $("keyDlg");
    $("keyReward").textContent = `+${Math.round(stage.rewardMs / 60000)}m`;
    $("keyRewardTitle").textContent = `${stage.label} — key ${stage.order} of 5`;
    $("keyRewardDetail").textContent =
      `Your deadline moves back by ${Math.round(stage.rewardMs / 60000)} minutes. ` +
      `You now have ${formatDuration(data.remainingMs)} left` +
      (data.keys.next ? `, and the next key is open.` : `, and the chain is complete.`);
    if (dialog) dialog.style.display = "flex";
  }

  function hideReward() {
    const dialog = $("keyDlg");
    if (dialog) dialog.style.display = "none";
  }

  async function submit(event) {
    event.preventDefault();
    const input = $("keyInput");
    const value = String(input?.value || "").trim();
    if (!value) return;

    const button = event.target.querySelector("button[type=submit]");
    if (button) button.disabled = true;
    setStatus("Checking…");

    try {
      const payload = await api.submitKey(value);
      state.set(payload.data.state);
      if (input) input.value = "";
      setStatus("", null);
      showReward(payload.data.stage, payload.data.state);
    } catch (error) {
      if (error.status === 422) {
        setStatus("That is not the key for this stage.", "error");
      } else if (error.status === 409) {
        setStatus(error.message, "error");
      } else if (error.status === 503) {
        setStatus("We could not verify that just now. Try again in a moment.", "error");
      } else {
        setStatus(error.message || "Something went wrong.", "error");
      }
    } finally {
      if (button) button.disabled = false;
    }
  }

  function init() {
    const form = $("keyForm");
    if (!form) return;
    form.addEventListener("submit", submit);
    $("keyInput")?.addEventListener("input", () => setStatus("", null));
    $("keyRewardClose")?.addEventListener("click", hideReward);
    $("keyDlg")?.addEventListener("click", event => {
      if (event.target.id === "keyDlg") hideReward();
    });
    document.addEventListener("keydown", event => {
      if (event.key === "Escape") hideReward();
    });
    state.subscribe(render);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

##### api.js
/**
 * The only way this page talks to the backend.
 *
 * There is nothing to configure here and nothing worth reading: every value
 * that decides anything — the clock, the keys, the twist, the credentials —
 * is computed on the server and arrives as already-decided facts.
 */
window.VELA_API = (() => {
  const SESSION_KEY = "vela.dev.session.v1";

  function token() {
    try {
      return localStorage.getItem(SESSION_KEY) || "";
    } catch {
      return "";
    }
  }

  function setToken(value) {
    try {
      if (value) localStorage.setItem(SESSION_KEY, value);
      else localStorage.removeItem(SESSION_KEY);
    } catch {
      /* private browsing */
    }
  }

  function hasToken() {
    return Boolean(token());
  }

  async function request(path, { method = "GET", body, auth = true, raw = false } = {}) {
    const headers = {};
    if (auth) {
      const current = token();
      if (!current) throw Object.assign(new Error("not signed in"), { status: 401 });
      headers.Authorization = `Bearer ${current}`;
    }
    if (body) headers["Content-Type"] = "application/json";

    const response = await fetch(path, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined
    });

    if (raw) return response;

    let payload = null;
    try {
      payload = await response.json();
    } catch {
      /* problem+json bodies are still JSON; anything else is a real failure */
    }

    if (!response.ok) {
      const error = new Error(payload?.detail || payload?.title || `HTTP ${response.status}`);
      error.status = response.status;
      error.payload = payload;
      throw error;
    }
    return payload;
  }

  /** Trades a Google ID token for a long-lived Vela session token. */
  async function openSession(googleIdToken) {
    const response = await fetch("/api/session", {
      method: "POST",
      headers: { Authorization: `Bearer ${googleIdToken}` }
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(payload?.detail || "could not open a session");
    }
    if (payload.session) setToken(payload.session);
    return payload.data;
  }

  function signOut() {
    setToken("");
  }

  return {
    hasToken,
    signOut,
    openSession,
    bootstrap: () => request("/api/bootstrap", { auth: false }),
    state: () => request("/api/state"),
    start: () => request("/api/start", { method: "POST" }),
    pause: () => request("/api/pause", { method: "POST" }),
    twist: () => request("/api/twist"),
    submitKey: key => request("/api/key", { method: "POST", body: { key } }),
    checkSubmission: () => request("/api/submit", { method: "POST" }),
    request
  };
})();
