1
 The premise
Today, buying a sports trip means opening six tabs, comparing prices that move when you refresh, guessing whether the hotel is near the courts, and booking out of exhaustion. AI is already dismantling that pattern, and we are only at the beginning of it.
We are not asking you to build a better booking site.
 We are asking you to build what replaces it.
In 2029 Vela has no homepage.
Build how a traveller comes to own a padel or tennis trip when there is no site to visit.
A submission that breaks any of these is not scored:
No search results page. No filter panel. No product grid. No comparison table.
The traveller is never handed a list to choose from. If your system's answer to 
"what should I book"
 is 
"here are twelve options"
, you have built the thing we asked you not to build.
Assume the traveller's attention is not on a screen for most of the interaction.
The entire purchase is reachable from a single expressed intent, in the traveller's own words.
Vela is not a destination. The traveller does not come to you. You arrive where they already are.
Not every buyer in 2029 has eyes, a screen, or patience.
We are not going to tell you what form this takes. Deciding that 
is
 the challenge, and the range of right answers is wider than you think. If your first instinct feels obvious, it pro
##### app.js
/**
 * View switching, the countdown, and the start gate.
 *
 * Everything rendered here is a projection of the last /api/state response.
 * There is no local clock state to tamper with: the only numbers that exist
 * came from the server, and the next poll overwrites whatever you change.
 */
(() => {
  const api = window.VELA_API;
  const state = window.VELA_STATE;

  const $ = id => document.getElementById(id);

  function show(el) {
    if (!el) return;
    el.classList.remove("hidden");
    el.removeAttribute("inert");
    el.removeAttribute("aria-hidden");
  }

  function hide(el) {
    if (!el) return;
    el.classList.add("hidden");
    el.setAttribute("inert", "");
    el.setAttribute("aria-hidden", "true");
  }

  function pad(value) {
    return String(value).padStart(2, "0");
  }

  function formatDuration(ms) {
    const total = Math.max(0, Math.floor(ms / 1000));
    return [
      pad(Math.floor(total / 3600)),
      pad(Math.floor((total % 3600) / 60)),
      pad(total % 60)
    ].join(":");
  }

  function initials(name) {
    return String(name || "")
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map(part => part[0].toUpperCase())
      .join("");
  }

  function avatarHue(email) {
    let hash = 0;
    for (const char of String(email)) hash = (hash * 31 + char.charCodeAt(0)) % 360;
    return `hsl(${hash} 42% 42%)`;
  }

  function escapeHtml(value) {
    return String(value).replace(/[&<>"']/g, ch => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;"
    }[ch]));
  }

  /* ---------------------------------------------------------------- */

  function renderIdentity(data) {
    $("userName").textContent = data.name;
    $("userEmail").textContent = data.email;
    const avatar = $("userAv");
    avatar.textContent = initials(data.name);
    avatar.style.background = avatarHue(data.email);
    const handoffEmail = $("handoffEmail");
    if (handoffEmail) handoffEmail.textContent = data.email;
  }

  function renderCredentials(data) {
    const body = $("credBody");
    if (!body) return;

    const credential = data.credential;
    if (!credential) {
      body.innerHTML =
        '<p class="cred-empty">Your credentials have not been issued yet. ' +
        "If your clock is running and this is still empty, contact us before you lose time.</p>";
      return;
    }

    const rows = [
      ["Base URL", credential.baseUrl],
      ["API key", credential.apiKey],
      ["Stripe publishable key", credential.stripePublishableKey],
      ["Brands", (credential.brands || []).join(", ")]
    ].filter(([, value]) => value);

    body.innerHTML =
      rows
        .map(
          ([label, value]) =>
            `<div class="cred-row"><span class="cred-label">${escapeHtml(label)}</span>` +
            `<code class="cred-value">${escapeHtml(value)}</code></div>`
        )
        .join("") +
      (credential.note ? `<p class="cred-note">${escapeHtml(credential.note)}</p>` : "") +
