  async function pressStart() {
    const button = $("readyStart");
    if (button) {
      button.disabled = true;
      button.textContent = "Opening the brief…";
    }
    try {
      const payload = await api.start();
      state.set(payload.data);
      // A reload is the path a returning candidate already takes, so the app
      // boots once with a running clock rather than being switched on midway.
      window.location.reload();
    } catch (error) {
      if (button) {
        button.disabled = false;
        button.textContent = "Start the challenge";
      }
      console.error("could not start:", error);
    }
  }

  async function togglePause() {
    const toggle = $("timerToggle");
    if (toggle) toggle.disabled = true;
    try {
      const payload = await api.pause();
      state.set(payload.data);
    } catch (error) {
      console.error("could not toggle pause:", error);
    } finally {
      renderClock();
    }
  }

  function wireUserMenu() {
    const chip = $("userChip");
    const menu = $("userMenu");
    if (!chip || !menu) return;
    chip.addEventListener("click", event => {
      event.stopPropagation();
      menu.classList.toggle("hidden");
    });
    document.addEventListener("click", () => menu.classList.add("hidden"));
  }

