  async function boot() {
    let config = {};
    try {
      config = (await api.bootstrap()).data;
    } catch (error) {
      console.error("could not reach the challenge backend:", error);
    }

    await window.VELA_AUTH.init(config);

    $("readyStart")?.addEventListener("click", pressStart);
    $("timerToggle")?.addEventListener("click", togglePause);
    wireUserMenu();

    if (!api.hasToken()) {
      showLogin();
      return;
    }

    const data = await state.refresh();
    if (!data) {
      showLogin();
      return;
    }

    if (data.started) showApp(data);
    else showReadyGate(data);

    state.subscribe(next => {
      if (!next) return;
      if (next.started) {
        renderIdentity(next);
        renderCredentials(next);
      }
      renderClock();
