##### state.js
/**
 * The candidate state, as the server last described it.
 *
 * Nothing here is authoritative. The clock ticks locally between polls purely
 * so the countdown moves smoothly, and every tick is re-anchored to the
 * server's own timestamp the moment a fresh state arrives. Editing anything in
 * this module changes what you see and nothing about what is true.
 */
window.VELA_STATE = (() => {
  const POLL_MS = 20000;

  let current = null;
  // Offset between this device's clock and the server's, so a candidate who
  // moves their system clock only succeeds in making their own display wrong.
  let skewMs = 0;
  let receivedAt = 0;
  const listeners = new Set();

  function subscribe(fn) {
    listeners.add(fn);
    if (current) fn(current);
    return () => listeners.delete(fn);
  }

  function emit() {
    for (const fn of listeners) {
      try {
        fn(current);
      } catch (error) {
        console.error("state listener failed:", error);
      }
    }
  }

  function set(next) {
    if (!next) return;
    current = next;
    receivedAt = Date.now();
    skewMs = (next.serverNow || receivedAt) - receivedAt;
    emit();
  }

  function get() {
    return current;
  }

  /** Server time as best this page can estimate it. */
  function serverNow() {
    return Date.now() + skewMs;
  }

  /** Either kind of stop the server can report: the candidate's, or ours. */
  function stopped() {
    return Boolean(current?.paused || current?.held);
  }

  /**
   * Remaining milliseconds, interpolated from the last server answer.
   * Frozen while paused or held, and never allowed below zero.
   */
  function remainingMs() {
    if (!current) return 0;
    if (stopped()) return current.remainingMs;
    const drift = Date.now() - receivedAt;
    return Math.max(0, current.remainingMs - drift);
  }

  function msUntilTwist() {
    if (!current) return 0;
    if (stopped()) return current.twist.opensInMs;
    const drift = Date.now() - receivedAt;
    return Math.max(0, current.twist.opensInMs - drift);
  }

  function expired() {
    return Boolean(current?.started) && !current?.held && remainingMs() <= 0;
  }

  async function refresh() {
    try {
      const payload = await window.VELA_API.state();
      set(payload.data);
      return payload.data;
    } catch (error) {
      if (error.status === 401) {
        window.VELA_API.signOut();
        window.location.reload();
      }
      return null;
    }
  }

  function startPolling() {
    refresh();
    setInterval(refresh, POLL_MS);
    // A candidate coming back to the tab should see the truth immediately
    // rather than up to twenty seconds of stale countdown.
    document.addEventListener("visibilitychange", () => {
      if (!document.hidden) refresh();
    });
  }

  return {
    subscribe,
    set,
    get,
    refresh,
    startPolling,
    serverNow,
    stopped,
    remainingMs,
    msUntilTwist,
    expired
  };
})();
##### twist.js
/**
 * Fetching the twist, once the server agrees it is time.
 *
 * There is no ciphertext in this bundle, no key, and no nonce. The twist text
 * exists only on the server, which answers 403 until the candidate's recorded
 * worked time passes twelve hours. Asking early is logged.
 */
(() => {
  const api = window.VELA_API;
  const state = window.VELA_STATE;

  let loaded = false;
  let loading = false;

  async function load() {
    if (loaded || loading) return;
    loading = true;
    try {
      const payload = await api.twist();
      const body = document.getElementById("twistBody");
      if (body) {
        body.innerHTML = payload.data.html;
        body.classList.add("is-open");
      }
      document.getElementById("twistLock")?.classList.add("hidden");
      loaded = true;
    } catch (error) {
      // 403 simply means not yet; the countdown already says so.
      if (error.status !== 403) console.error("could not load the twist:", error);
    } finally {
      loading = false;
    }
  }

  function init() {
    state.subscribe(data => {
      if (data?.twist?.unlocked) load();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
##### submission.js
/**
 * Handing candidates over to the submission form, and confirming they arrived.
 *
 * A Google Form with file upload cannot be embedded, so the form opens in its
 * own tab and this page cannot observe the submission first hand. It asks the
 * backend instead, which checks the response sheet — so a candidate cannot mark
 * themselves submitted without having actually submitted, and the timestamp
 * recorded is the server's rather than anything the client offers.
 */
(() => {
  const api = window.VELA_API;
  const state = window.VELA_STATE;

  const $ = id => document.getElementById(id);
  let checking = false;

  function setStatus(message, tone) {
    const el = $("handoffStatus");
    if (!el) return;
    el.textContent = message || "";
    el.classList.toggle("is-error", tone === "error");
    el.classList.toggle("is-ok", tone === "ok");
  }

  function renderReceipt(data) {
    if (!data?.submission) return;
    $("handoff")?.classList.add("hidden");
    const receipt = $("receipt");
    if (!receipt) return;
    receipt.classList.remove("hidden");
    $("receiptWhen").textContent = new Date(data.submittedAt).toLocaleString("en-GB");
    $("receiptRepo").textContent = data.submission.repoUrl || "—";
  }

  async function check({ quiet } = {}) {
    if (checking) return false;
    checking = true;
    if (!quiet) setStatus("Checking your submission…");

    try {
      const payload = await api.checkSubmission();
      state.set(payload.data);
      if (payload.data.submitted) {
        setStatus("", null);
        renderReceipt(payload.data);
        return true;
      }
      if (!quiet) {
        setStatus(
          `No submission found yet for ${payload.data.email}. Make sure you signed in to the ` +
            "form with that same account, then try again.",
          "error"
        );
      }
      return false;
    } catch (error) {
      if (!quiet) setStatus(error.message || "Could not reach the submission log.", "error");
      return false;
    } finally {
      checking = false;
    }
  }

  function init(data) {
    const panel = $("handoff");
    if (!panel || !data?.started) return;

    if (data.submitted) {
      renderReceipt(data);
      return;
    }

    const openBtn = $("openFormBtn");
    if (openBtn) {
      if (data.submissionFormUrl) {
        openBtn.href = data.submissionFormUrl;
        // Coming back from the form tab is the natural moment to look.
        openBtn.addEventListener("click", () => {
          window.addEventListener("focus", () => check({ quiet: true }), { once: true });
        });
      } else {
        openBtn.setAttribute("aria-disabled", "true");
        openBtn.classList.add("is-disabled");
        openBtn.addEventListener("click", event => event.preventDefault());
        setStatus("The submission form is not configured yet. Contact us before your time runs out.", "error");
      }
    }

    $("checkSubmitBtn")?.addEventListener("click", () => check());
    check({ quiet: true });
  }

  let started = false;
  state.subscribe(data => {
    if (started || !data?.started) return;
    started = true;
    init(data);
  });
})();
